preConditionHook:
// STOP BEYOND THE START OF THE SPIKE, not beyond the signal or entry bar. For a
// trade taken during a spike the reference bar is the FIRST bar of the run of
// strong trend bars, which can be several bars before the entry, so this stop is
// deliberately wider than StopBeyondSignalBar.
//
// THE SPIKE'S START COMES FROM THE SETTLED ALWAYS-IN DECISION: a strong trend bar
// has a body of at least strongBodyFraction of its own range with BOTH tails no
// more than maxTailFraction of it, and consecutiveBars (default 2) of them in a
// row is the flip. The run's first bar's low is carried in a local while the run
// extends, so no bar index grows with the spike's length -- the deepest bar this
// rule touches is 0. Both body and tail tests are MULTIPLICATIONS, never
// divisions, so a zero-range bar cannot raise EL's divide-by-zero.
//
// THE LEVEL IS FROZEN AT ENTRY. The spike level is market state that keeps
// updating as new spikes print, but the stop is the spike the trade was ENTERED
// in, so it is captured on the fill bar and never moved -- which is what makes
// this an initial stop rather than another trail, and it is the at-entry capture
// convention StopAtSignalBarRangeMultiple uses. A trade entered before any spike
// has printed never fires this exit, which the have-flags carry.
//
// ctx.BarsSinceEntry() == 0 is the per-position boundary: VERIFIED as 0 on the
// fill bar and as restarting through a reversal, which a ctx.MarketPosition() == 0
// reset would miss because a reversal never passes through flat.
//
// The run counters are ints compared against a double input, so the cast is
// explicit, as BreakevenStopAfterEmaHoldingRun writes it.
//
// Ticks: MinMove/PriceScale are VERIFIED and the tick is written division-first,
// stopBufferTicks * (ctx.MinMove() / ctx.PriceScale()), into a local.
//
// Every scratch value is a localVariables entry, never a hook-scope declaration,
// so the hooks survive a double placement.
//
// Deepest bar touched: 0.
tickSize = ctx.MinMove() / ctx.PriceScale();
barRange = high[0] - low[0];
bodySize = close[0] - open[0];
strongBull = el_gt(close[0], open[0]) && el_ge(bodySize, strongBodyFraction * barRange) && el_le(high[0] - close[0], maxTailFraction * barRange) && el_le(open[0] - low[0], maxTailFraction * barRange);
strongBear = el_lt(close[0], open[0]) && el_ge(-bodySize, strongBodyFraction * barRange) && el_le(high[0] - open[0], maxTailFraction * barRange) && el_le(close[0] - low[0], maxTailFraction * barRange);
if (strongBull) {
    if (bullRunLen == 0) bullRunLow = low[0];
    bullRunLen = bullRunLen + 1;
} else {
    bullRunLen = 0;
}
if (strongBear) {
    if (bearRunLen == 0) bearRunHigh = high[0];
    bearRunLen = bearRunLen + 1;
} else {
    bearRunLen = 0;
}
if (el_ge((double)bullRunLen, consecutiveBars)) {
    spikeLow = bullRunLow;
    haveSpikeLow = true;
}
if (el_ge((double)bearRunLen, consecutiveBars)) {
    spikeHigh = bearRunHigh;
    haveSpikeHigh = true;
}
if (ctx.BarsSinceEntry() == 0) {
    haveStopLong = haveSpikeLow;
    stopLong = spikeLow;
    haveStopShort = haveSpikeHigh;
    stopShort = spikeHigh;
}
